 IEnumerator Start(){folder=SportsEvidencePaths.Folder("MattressWorldEvidence");File.WriteAllText(folder+"/result.txt","RUNNING "+DateTime.UtcNow.ToString("O"));yield return SportsProbeScene.Ensure<MattressMatch>("TruckMattressRacing");m=FindAnyObjectByType<MattressMatch>();yield return null;had=SportsPrefs.HasKey(m.PreferenceKey);saved=SportsPrefs.GetString(m.PreferenceKey);Application.logMessageReceived+=Error;m.SetupScreen();m.AllBots();m.option=1;Check(m.StartMatch(),"physical scenery fixture starts");while(m.Phase==MattressPhase.Countdown)yield return null;m.enabled=false;for(int i=1;i<8;i++){m.racers[i].truck.body.isKinematic=true;m.racers[i].truck.body.detectCollisions=false;}var world=m.world;Check(world!=null&&world.obstacles.Length==32&&world.walkers.Length==8&&m.replay.sources.Length==9,"bounded scenery pools and ninth actual-world replay source exist");var sheep=world.obstacles.First(o=>o.kind==MattressObstacleKind.Sheep);var tree=world.obstacles.First(o=>o.kind==MattressObstacleKind.Tree);tree.ResetObstacle(m.course.Surface(sheep.transform.position+Vector3.right*4),Quaternion.identity);m.replay.ResetRecord();m.replay.Record(0,511);var truck=m.racers[0].truck;truck.body.position=sheep.transform.position+Vector3.up*.65f-Vector3.forward*.35f;truck.body.rotation=m.course.Rotation(sheep.transform.position.z);truck.body.linearVelocity=truck.body.rotation*Vector3.forward*8;truck.body.angularVelocity=Vector3.zero;Physics.SyncTransforms();float until=Time.realtimeSinceStartup+3;while(!sheep.Fired&&Time.realtimeSinceStartup<until)yield return null;yield return new WaitForFixedUpdate();yield return null;Check(sheep.Fired&&world.Explosions==1&&!sheep.shape.enabled,"real truck/trigger contact explodes the sheep exactly once");Check(tree.tree.KnockedDown&&tree.tree.Blasts==1,"actual nearby sheep explosion releases the existing physical tree roots");yield return new WaitForSeconds(.4f);Check(world.Explosions==1&&truck.body.linearVelocity.magnitude<35,"overlap cannot repeat explosion and physical blast stays bounded");var walker=world.walkers[0];truck.body.position=walker.transform.position+Vector3.up*.55f-Vector3.forward*.3f;truck.body.rotation=Quaternion.identity;truck.body.linearVelocity=Vector3.forward*8;truck.body.angularVelocity=Vector3.zero;Physics.SyncTransforms();until=Time.realtimeSinceStartup+3;while(world.PedestrianHits==0&&Time.realtimeSinceStartup<until)yield return null;Check(world.PedestrianHits>0&&walker.pedestrian.IsRagdoll,"actual moving-truck contact triggers the existing Taxi pedestrian ragdoll");yield return new WaitForSeconds(6.2f);Check(!tree.shape.enabled&&!tree.body.detectCollisions,"fallen tree cannot permanently block the course after its grace");world.Freeze();foreach(var racer in m.racers)racer.truck.body.isKinematic=true;m.replay.Record(1,511);var live=world.GetComponentsInChildren<Transform>(true);int treeIndex=Array.IndexOf(live,tree.transform),sheepIndex=Array.IndexOf(live,sheep.transform);m.replay.Begin();m.replay.Seek(1);var ghost=m.replay.ghosts[8].GetComponentsInChildren<Transform>(true);Check(ghost.Length==live.Length&&treeIndex>=0&&sheepIndex>=0&&Quaternion.Angle(ghost[treeIndex].localRotation,tree.transform.localRotation)<.01f&&ghost[sheepIndex].localScale==Vector3.zero,"actual destruction poses and hidden exploded sheep reproduce in ninth render-only replay");Check(m.replay.ghosts.All(g=>g.GetComponentsInChildren<Collider>(true).Length==0&&g.GetComponentsInChildren<Rigidbody>(true).Length==0),"world replay has no physical authority");m.replay.End();world.ResetWorld(24680);var positions=world.obstacles.Select(o=>o.body.position).ToArray();world.ResetWorld(24680);var resetDetails=string.Join(";",world.obstacles.Select((o,i)=>"i="+i+" d="+Vector3.Distance(o.body.position,positions[i]).ToString("R")+" shape="+o.shape.enabled+" fired="+o.Fired));Check(world.obstacles.Select((o,i)=>Vector3.Distance(o.body.position,positions[i])<.001f&&o.shape.enabled&&!o.Fired).All(v=>v)&&!tree.tree.KnockedDown&&world.walkers.All(w=>!w.pedestrian.IsRagdoll),"same seed restores every physical obstacle within1mm engine pose precision and every walker without stale destruction; tree="+tree.tree.KnockedDown+" ragdolls="+string.Join(",",world.walkers.Select(w=>w.pedestrian.IsRagdoll))+" objects="+resetDetails);m.enabled=true;m.SetupScreen();Restore();SportsNavigation.FrontEnd();yield return null;yield return null;Check(FindObjectsByType<AudioListener>().Length==1,"scenery fixture exits without duplicate listeners");log.AppendLine("ERRORS="+errors+". Labelled initial poses/velocities followed by actual PhysX triggers, bounded sheep blast, vendor tree roots/Taxi ragdoll and recorded transforms. Full AI races are separate evidence; no human/hardware test.");File.WriteAllText(folder+"/result.txt",log.ToString());if(!Application.isEditor)Application.Quit(errors==0?0:2);}
